insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Adult/Teen: Diamond Painting Craft','The library lists a diamond-painting craft session for adults and teens in the Wadsworth Room. Confirm materials and any registration requirements directly. Official occurrence checked November 6, 2026; no images reused.','Tracy','Tracy Branch Library, Wadsworth Room, 20 East Eaton Avenue, Tracy','2026-11-07T11:00:00-08:00','2026-11-07T13:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/tracy/november-2026/adult-teen-diamond-painting-craft?id=1794078000-246764','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Tracy' and source_url='https://www.ssjcpl.org/events-services/events-calendar/tracy/november-2026/adult-teen-diamond-painting-craft?id=1794078000-246764' and start_date='2026-11-07T11:00:00-08:00'::timestamptz);
