insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Shedskin Reptile Experience','The library lists a free, all-ages reptile presentation with Shedskin Reptiles. Its branch calendar directs November 10 Lego Club attendees to this replacement program. Confirm attendance details directly. Official occurrence and branch address checked November 6, 2026; no images reused.','Manteca','Manteca Branch Library, 320 W Center Street, Manteca','2026-11-10T15:30:00-08:00','2026-11-10T16:30:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/shedskin-reptile-experience?id=1794353400-247246','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Manteca' and source_url='https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/shedskin-reptile-experience?id=1794353400-247246' and start_date='2026-11-10T15:30:00-08:00'::timestamptz);
